<?php
require __DIR__.'/../config/koneksi.php';require_admin();$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$act=$_POST['action']??'';try{if($act==='save'){$id=(int)($_POST['id']??0);$n=trim($_POST['nama_kategori']??'');if($n==='')throw new Exception('Nama kategori wajib diisi.');if($id){$q=$pdo->prepare('UPDATE kategori SET nama_kategori=? WHERE id=?');$q->execute([$n,$id]);}else{$q=$pdo->prepare('INSERT INTO kategori(nama_kategori) VALUES(?)');$q->execute([$n]);}$msg='Kategori tersimpan.';}if($act==='delete'){$q=$pdo->prepare('DELETE FROM kategori WHERE id=?');$q->execute([(int)$_POST['id']]);$msg='Kategori dihapus.';}}catch(Throwable $e){$msg='Tidak dapat menyimpan kategori. Nama mungkin sudah digunakan.';}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM kategori WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$rows=$pdo->query('SELECT k.*,COUNT(p.id) jumlah FROM kategori k LEFT JOIN produk p ON p.id_kategori=k.id GROUP BY k.id ORDER BY k.nama_kategori')->fetchAll();page_start('Manajemen Kategori');?>
<?php if($msg): ?><div class="alert alert-info"><?=e($msg)?></div><?php endif; ?><div class="row g-3"><div class="col-md-4"><div class="panel-card"><h3 class="mb-3"><?= $edit?'Edit':'Tambah' ?> Kategori</h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><input class="form-control mb-3" name="nama_kategori" required placeholder="Nama kategori" value="<?=e($edit['nama_kategori']??'')?>"><button class="btn btn-primary w-100">Simpan</button></form></div></div><div class="col-md-8"><div class="panel-card"><div class="table-responsive"><table class="table modern-table"><thead><tr><th>Nama Kategori</th><th>Jumlah Produk</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['nama_kategori'])?></td><td><?=$r['jumlah']?></td><td><a class="btn btn-sm btn-outline-primary" href="?edit=<?=$r['id']?>">Edit</a> <form class="d-inline" method="post" onsubmit="return confirm('Hapus kategori? Produk akan menjadi tanpa kategori.')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-danger">Hapus</button></form></td></tr><?php endforeach; ?></tbody></table></div></div></div></div><?php page_end(); ?>
